// Generated Base64 Cash Drawer Pixel Art Image (Clean crop, 0% background, 100% reliable)
import 'dart:convert';
import 'dart:typed_data';

class DrawerImageData {
  static Uint8List? _bytes;

  static Uint8List get bytes {
    _bytes ??= base64Decode(_base64);
    return _bytes!;
  }

  static const String _base64 = '';
}